package mrpapermoon.whisper.serviceimport android.content.Contextimport androidx.annotation.CallSuperimport com.google.android.gms.nearby.Nearbyimport kotlinx.coroutines.channels.ChannelResultimport kotlinx.coroutines.channels.SendChannelimport kotlinx.coroutines.flow.Flowinternal abstract class NetworkConnectionsWrapper(private val actor: SendChannel<Event>, context: Context) :	SendChannel<NetworkConnectionsWrapper.Event> by actor {	protected val connectionsClient = Nearby.getConnectionsClient(context)	abstract val activeEndpoints: List<String>	@CallSuper	open fun stopNetwork() {		actor.close()	}	protected fun sendEvent(event: Event): ChannelResult<Unit> = actor.trySend(event)	sealed interface Event {		data class NewConnection(val endpointId: String) : Event		data class DropConnection(val endpointId: String) : Event		data class OnStream(val byteStream: Flow<ByteArray>) : Event		data class OnMessage(val payload: ByteArray) : Event {			override fun equals(other: Any?): Boolean {				if (this === other) return true				if (javaClass != other?.javaClass) return false				other as OnMessage				return payload.contentEquals(other.payload)			}			override fun hashCode(): Int {				return payload.contentHashCode()			}		}	}	companion object Factory {		suspend operator fun invoke(			actor: SendChannel<Event>,			context: Context,			serviceId: String,			uuid: String,		): NetworkConnectionsWrapper {			return NetworkConnectionsWrapperImpl(actor, context, serviceId, uuid)				.also { it.startNetwork() }		}	}}